import java.util.ArrayList;
import java.util.List;
import java.util.function.IntUnaryOperator;
import java.util.function.Supplier;

public class CapturingFactoryTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void checkCall(String label, Object expected, java.util.concurrent.Callable<Object> call) {
        Object actual;
        try {
            actual = call.call();
        } catch (Throwable t) {
            actual = t.getClass().getSimpleName();
        }
        check(label, expected, actual);
    }

    public static void main(String[] args) {
        List<IntUnaryOperator> adders = CapturingFactory.makeAdders(List.of(1, 10));
        check("makeAdders size", 2, adders.size());
        checkCall("first adder on 5", 6, () -> adders.get(0).applyAsInt(5));
        checkCall("second adder on 5", 15, () -> adders.get(1).applyAsInt(5));
        checkCall("each lambda kept its own offset", 21,
                () -> adders.get(0).applyAsInt(0) + adders.get(1).applyAsInt(10));

        check("applyAll runs every step", 6, CapturingFactory.applyAll(CapturingFactory.makeAdders(List.of(1, 2, 3)), 0));
        check("applyAll on no steps", 4, CapturingFactory.applyAll(new ArrayList<IntUnaryOperator>(), 4));

        Supplier<String> labeler = CapturingFactory.makeLabeler("user", 7);
        checkCall("labeler.get()", "user-7", () -> labeler.get());
        checkCall("labeler is stable across calls", "user-7user-7", () -> labeler.get() + labeler.get());

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

