import java.util.ArrayList;
import java.util.List;
import java.util.function.IntUnaryOperator;
import java.util.function.Supplier;

public class CapturingFactory {

    public static List<IntUnaryOperator> makeAdders(List<Integer> offsets) {
        List<IntUnaryOperator> adders = new ArrayList<>();
        for (int offset : offsets) {
            int captured = offset;
            adders.add(value -> value + captured);
        }
        return adders;
    }

    public static Supplier<String> makeLabeler(String prefix, int id) {
        return () -> prefix + "-" + id;
    }

    public static int applyAll(List<IntUnaryOperator> steps, int start) {
        int current = start;
        for (IntUnaryOperator step : steps) {
            current = step.applyAsInt(current);
        }
        return current;
    }
}
